const D = { energy:.6, density:.55, speed:1, scale:1, hue:350, x:.5, y:.5, style:'veil', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const md = Math.max(width, height);
const style = P.style, sd = (P.seed | 0);
const TAU = Math.PI * 2;
const smooth = t => t < 0 ? 0 : t > 1 ? 1 : t * t * (3 - 2 * t);
const hw = h => ((h % 360) + 360) % 360;

const T = K.t * (0.4 + P.speed * 0.6);
const cx = P.x * width, cy = P.y * height;
const Rmax = 1.35 * md * (0.7 + P.scale * 0.5);
const NS = Math.round(3 + P.density * 3);

// ---- shell registry (reset-safe, seed-rebuild) ----
if (!S.sh || S.shSeed !== sd || S.shN !== NS || S.lastT == null || T < S.lastT) {
  S.shSeed = sd; S.shN = NS; S.sh = [];
  const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
  for (let k = 0; k < NS; k++) {
    S.sh.push({ speed: (0.045 + fr(k*5+1) * 0.03) * md, birth: T - fr(k*5+2) * (Rmax / ((0.045 + fr(k*5+1)*0.03) * md)), sseed: (sd * 7 + k * 131) >>> 0, ell: 0.82 + fr(k*5+3) * 0.3 });
  }
}
S.lastT = T;
const frs = (a, so) => { const s = Math.sin(a * 12.9898 + so * 0.017) * 43758.5453; return s - Math.floor(s); };

// deep-space toned ground (never dead black) + faint remnant haze
push();
noStroke();
const gg = drawingContext.createRadialGradient(cx, cy, 1, cx, cy, md * 0.8);
if (style === 'ink') { gg.addColorStop(0, 'rgba(26,24,30,1)'); gg.addColorStop(1, 'rgba(10,10,14,1)'); }
else { gg.addColorStop(0, 'rgba(14,10,22,1)'); gg.addColorStop(0.5, 'rgba(9,8,18,1)'); gg.addColorStop(1, 'rgba(5,6,12,1)'); }
drawingContext.fillStyle = gg; drawingContext.fillRect(0, 0, width, height);
pop();

const filStrands = Math.round(20 + P.density * 46);
const expo = 0.5 + P.energy * 1.1;
const hb = P.hue;

push();
blendMode(ADD);
for (let s = 0; s < S.sh.length; s++) {
  const sh = S.sh[s];
  let R = sh.speed * (T - sh.birth);
  if (R > Rmax) { sh.birth = T; sh.sseed = (sh.sseed * 1664525 + 1013904223) >>> 0; R = 0.001; }
  const so = sh.sseed;
  const fadeIn = smooth(R / (0.16 * md));
  const fadeOut = smooth((Rmax - R) / (0.45 * Rmax));
  const amp = fadeIn * fadeOut;
  if (amp <= 0.001) continue;
  const ell = sh.ell;

  // 1) broad diffuse shock glow (carries luminance + motion as it expands)
  const inR = Math.max(1, R * 0.55), outR = R * 1.12;
  const glow = drawingContext.createRadialGradient(cx, cy, inR, cx, cy, outR);
  let gc;
  if (style === 'oxygen') gc = [90, 200, 180];
  else if (style === 'xray') gc = [140, 190, 255];
  else if (style === 'ink') gc = [150, 150, 165];
  else gc = [180, 90, 130];
  const ga = (0.05 + P.energy * 0.09) * amp * (P.alpha / 100);
  const grd = drawingContext.createRadialGradient(cx, cy, inR * 0.4, cx, cy, outR);
  grd.addColorStop(0, `rgba(${gc[0]},${gc[1]},${gc[2]},0)`);
  grd.addColorStop(0.72, `rgba(${gc[0]},${gc[1]},${gc[2]},${ga * 0.5})`);
  grd.addColorStop(0.9, `rgba(${gc[0]},${gc[1]},${gc[2]},${ga})`);
  grd.addColorStop(1, `rgba(${gc[0]},${gc[1]},${gc[2]},0)`);
  drawingContext.fillStyle = grd; drawingContext.fillRect(0, 0, width, height);

  // 2) delicate expanding filaments (Veil-like wisps)
  const drift = T * 0.02 + s * 1.7;
  noFill();
  for (let k = 0; k < filStrands; k++) {
    const base = frs(k + 1, so) * TAU + drift;
    const arc = 0.10 + frs(k + 30, so) * 0.22;
    const rjit = 0.02 + frs(k + 60, so) * 0.06;
    // choose emission line: red H-alpha, cyan/green OIII, or violet
    const lc = frs(k + 90, so);
    let h, sat;
    if (style === 'oxygen') { h = hw(hb + 190 + lc * 40); sat = 70; }
    else if (style === 'xray') { h = hw(200 + lc * 40); sat = 30 + lc * 30; }
    else if (style === 'ink') { h = 0; sat = 0; }
    else { if (lc < 0.5) { h = hw(hb + lc * 20); sat = 82; } else if (lc < 0.82) { h = hw(185 + lc * 30); sat = 68; } else { h = hw(275 + lc * 20); sat = 60; } }
    const bright = (46 + frs(k + 120, so) * 44) * expo * amp;
    const sw = (0.5 + frs(k + 150, so) * 1.3) * (u / 700);
    strokeWeight(sw);
    const NP = 11;
    beginShape();
    for (let p = 0; p <= NP; p++) {
      const tt = p / NP;
      const a = base + (tt - 0.5) * arc;
      // wispy turbulent radial displacement (Rayleigh-Taylor fingers)
      const turb = Math.sin(a * 7 + so * 0.01) * 0.5 + Math.sin(a * 13 + k) * 0.3 + Math.sin(a * 23 + so) * 0.2;
      const rr = R * (1 + turb * rjit + Math.sin(tt * 6.28 + k) * 0.01);
      const px = cx + Math.cos(a) * rr;
      const py = cy + Math.sin(a) * rr * ell;
      // per-point brightness (brightest at shock front midpoint)
      const b = bright * (0.4 + 0.6 * Math.sin(tt * Math.PI));
      stroke(style === 'ink' ? 0 : h, sat, style === 'ink' ? (30 + b) : Math.min(100, 55 + b * 0.4), Math.min(80, b) * (P.alpha / 100));
      curveVertex(px, py);
    }
    endShape();
  }
}
// faint central compact remnant (neutron star) — subtle, non-strobe
noStroke();
const tw = 0.7 + 0.3 * Math.sin(T * 0.8) + K.pulse * 0.2 + A.bass * 0.25;
if (style !== 'ink') {
  fill(200, 20, 100, (8 + P.energy * 8) * tw * (P.alpha / 100));
  circle(cx, cy, u * 0.02 * tw);
}
blendMode(BLEND);
pop();
